CREATE TABLE profiles (user_id TEXT PRIMARY KEY, handle TEXT NOT NULL UNIQUE, name TEXT NOT NULL, avatar_seed TEXT NOT NULL DEFAULT 'aori', bio TEXT NOT NULL DEFAULT '', created INTEGER NOT NULL, last_seen INTEGER NOT NULL);
CREATE TABLE wallets (user_id TEXT PRIMARY KEY REFERENCES profiles(user_id), sigma INTEGER NOT NULL DEFAULT 40 CHECK(sigma >= 0), shards INTEGER NOT NULL DEFAULT 0 CHECK(shards >= 0), ink INTEGER NOT NULL DEFAULT 0 CHECK(ink >= 0));
CREATE TABLE ledger (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES profiles(user_id), currency TEXT NOT NULL, amount INTEGER NOT NULL, reason TEXT NOT NULL, ref TEXT NOT NULL, created INTEGER NOT NULL, UNIQUE(user_id,currency,ref));
CREATE TABLE friend_requests (sender TEXT NOT NULL REFERENCES profiles(user_id), recipient TEXT NOT NULL REFERENCES profiles(user_id), status TEXT NOT NULL DEFAULT 'pending', created INTEGER NOT NULL, PRIMARY KEY(sender,recipient));
CREATE TABLE friendships (a TEXT NOT NULL REFERENCES profiles(user_id), b TEXT NOT NULL REFERENCES profiles(user_id), created INTEGER NOT NULL, PRIMARY KEY(a,b));
CREATE TABLE messages (id TEXT PRIMARY KEY, sender TEXT NOT NULL REFERENCES profiles(user_id), recipient TEXT NOT NULL REFERENCES profiles(user_id), text TEXT NOT NULL, expression TEXT, created INTEGER NOT NULL, read_at INTEGER);
CREATE INDEX messages_pair ON messages(sender,recipient,created);
CREATE TABLE clans (id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE, tag TEXT NOT NULL UNIQUE, description TEXT NOT NULL DEFAULT '', owner_id TEXT NOT NULL UNIQUE REFERENCES profiles(user_id), created INTEGER NOT NULL);
CREATE TABLE clan_members (user_id TEXT PRIMARY KEY REFERENCES profiles(user_id), clan_id TEXT NOT NULL REFERENCES clans(id), joined INTEGER NOT NULL);
CREATE INDEX clan_members_clan ON clan_members(clan_id);
CREATE TABLE invites (code TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES profiles(user_id), kind TEXT NOT NULL, clan_id TEXT REFERENCES clans(id), uses INTEGER NOT NULL DEFAULT 0, max_uses INTEGER NOT NULL DEFAULT 10, expires INTEGER NOT NULL, created INTEGER NOT NULL);
CREATE TABLE invite_claims (id TEXT PRIMARY KEY, code TEXT NOT NULL REFERENCES invites(code), user_id TEXT NOT NULL REFERENCES profiles(user_id), created INTEGER NOT NULL, UNIQUE(code,user_id));
CREATE TABLE promo_claims (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES profiles(user_id), code TEXT NOT NULL, currency TEXT NOT NULL, amount INTEGER NOT NULL, created INTEGER NOT NULL, UNIQUE(user_id,code));
CREATE TABLE coupons (code TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES profiles(user_id), currency TEXT NOT NULL, amount INTEGER NOT NULL, claimed_by TEXT REFERENCES profiles(user_id), created INTEGER NOT NULL, expires INTEGER NOT NULL);
CREATE TABLE posts (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES profiles(user_id), text TEXT NOT NULL, expression TEXT NOT NULL, result REAL NOT NULL, created INTEGER NOT NULL, story INTEGER NOT NULL DEFAULT 0);
CREATE TABLE war_runs (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES profiles(user_id), clan_a TEXT NOT NULL REFERENCES clans(id), clan_b TEXT NOT NULL REFERENCES clans(id), questions TEXT NOT NULL, round_index INTEGER NOT NULL DEFAULT 0, correct INTEGER NOT NULL DEFAULT 0, score INTEGER NOT NULL DEFAULT 0, bot_score INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'active', created INTEGER NOT NULL, updated INTEGER NOT NULL);
CREATE INDEX war_user ON war_runs(user_id,status,created);
CREATE TABLE war_scores (clan_id TEXT NOT NULL REFERENCES clans(id), season TEXT NOT NULL, points INTEGER NOT NULL DEFAULT 0, wins INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(clan_id,season));
CREATE TABLE rate_limits (user_id TEXT NOT NULL, action TEXT NOT NULL, slot INTEGER NOT NULL, count INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(user_id,action,slot));
